      "number": 10,
      "arFull": "لَقَدْ اَنْزَلْنَاۤ اِلَیْكُمْ كِتٰبًا فِیْهِ ذِكْرُكُمْ ؕ اَفَلَا تَعْقِلُوْنَ ۟۠",
