      "arFull": "قَالُوْا یٰوَیْلَنَاۤ اِنَّا كُنَّا ظٰلِمِیْنَ ۟",
      "ur": "کہنے لگے ہائے ہماری خرابی! بیشک ہم ﻇالم تھے.",
