      "arFull": "وَدَاوٗدَ وَسُلَیْمٰنَ اِذْ یَحْكُمٰنِ فِی الْحَرْثِ اِذْ نَفَشَتْ فِیْهِ غَنَمُ الْقَوْمِ ۚ وَكُنَّا لِحُكْمِهِمْ شٰهِدِیْنَ ۟ۗۙ",
