      "arFull": "وَزَكَرِیَّاۤ اِذْ نَادٰی رَبَّهٗ رَبِّ لَا تَذَرْنِیْ فَرْدًا وَّاَنْتَ خَیْرُ الْوٰرِثِیْنَ ۟ۚۖ",
