      "arFull": "لَا یَحْزُنُهُمُ الْفَزَعُ الْاَكْبَرُ وَتَتَلَقّٰىهُمُ الْمَلٰٓىِٕكَةُ ؕ هٰذَا یَوْمُكُمُ الَّذِیْ كُنْتُمْ تُوْعَدُوْنَ ۟",
